import { IS_NON_DIMENSIONAL } from '../constants';
import options from '../options';

function setStyle(style, key, value) {
	if (key[0] === '-') {
		style.setProperty(key, value == null ? '' : value);
	} else if (value == null) {
		style[key] = '';
	} else if (typeof value != 'number' || IS_NON_DIMENSIONAL.test(key)) {
		style[key] = value;
	} else {
		style[key] = value + 'px';
	}
}

function PropWriter() {
	this._useCapture = false;
	this._eventName = '';
}

/**
 * Set a property value on a DOM node
 * @param {object} patch The host property update to apply
 */
PropWriter.prototype.setProperty = function (patch) {
	o: if (patch.name === 'style') {
		if (typeof patch.value == 'string') {
			patch.dom.style.cssText = patch.value;
		} else {
			if (typeof patch.oldValue == 'string') {
				patch.dom.style.cssText = patch.oldValue = '';
			}

			if (patch.oldValue) {
				for (let i in patch.oldValue) {
					if (!(patch.value && i in patch.value)) {
						setStyle(patch.dom.style, i, '');
					}
				}
			}

			if (patch.value) {
				for (let i in patch.value) {
					if (!patch.oldValue || patch.value[i] !== patch.oldValue[i]) {
						setStyle(patch.dom.style, i, patch.value[i]);
					}
				}
			}
		}
	}
	// Benchmark for comparison: https://esbench.com/bench/574c954bdb965b9a00965ac6
	else if (patch.name[0] === 'o' && patch.name[1] === 'n') {
		this._useCapture =
			patch.name !==
			(patch.name = patch.name.replace(/(PointerCapture)$|Capture$/i, '$1'));

		// Infer correct casing for DOM built-in events:
		this._eventName = patch.name.toLowerCase();
		if (this._eventName in patch.dom) patch.name = this._eventName.slice(2);
		else patch.name = patch.name.slice(2);

		if (!patch.dom._listeners) patch.dom._listeners = {};
		patch.dom._listeners[patch.name + this._useCapture] = patch.value;

		if (patch.value) {
			if (!patch.oldValue) {
				patch.value._attached = Date.now();
				const handler = this._useCapture ? eventProxyCapture : eventProxy;
				patch.dom.addEventListener(patch.name, handler, this._useCapture);
			} else {
				patch.value._attached = patch.oldValue._attached;
			}
		} else {
			const handler = this._useCapture ? eventProxyCapture : eventProxy;
			patch.dom.removeEventListener(patch.name, handler, this._useCapture);
		}
	} else {
		if (patch.isSvg) {
			// Normalize incorrect prop usage for SVG:
			// - xlink:href / xlinkHref --> href (xlink:href was removed from SVG and isn't needed)
			// - className --> class
			patch.name = patch.name.replace(/xlink(H|:h)/, 'h').replace(/sName$/, 's');
		} else if (
			patch.name !== 'width' &&
			patch.name !== 'height' &&
			patch.name !== 'href' &&
			patch.name !== 'list' &&
			patch.name !== 'form' &&
			// Default value in browsers is `-1` and an empty string is
			// cast to `0` instead
			patch.name !== 'tabIndex' &&
			patch.name !== 'download' &&
			patch.name !== 'rowSpan' &&
			patch.name !== 'colSpan' &&
			patch.name !== 'role' &&
			patch.name in patch.dom
		) {
			try {
				patch.dom[patch.name] = patch.value == null ? '' : patch.value;
				// labelled break is 1b smaller here than a return statement (sorry)
				break o;
			} catch (e) {}
		}

		// aria- and data- attributes have no boolean representation.
		// A `false` value is different from the attribute not being
		// present, so we can't remove it. For non-boolean aria
		// attributes we could treat false as a removal, but the
		// amount of exceptions would cost too many bytes. On top of
		// that other frameworks generally stringify `false`.

		if (typeof patch.value == 'function') {
			// never serialize functions as attribute values
		} else if (
			patch.value != null &&
			(patch.value !== false || patch.name[4] === '-')
		) {
			patch.dom.setAttribute(patch.name, patch.value);
		} else {
			patch.dom.removeAttribute(patch.name);
		}
	}
};

const propWriter = new PropWriter();

/**
 * Set a property value on a DOM node
 * @param {PreactElement} dom The DOM node to modify
 * @param {string} name The name of the property to set
 * @param {*} value The value to set the property to
 * @param {*} oldValue The old value the property had
 * @param {boolean} isSvg Whether or not this DOM node is an SVG node or not
 */
export function setProperty(dom, name, value, oldValue, isSvg) {
	return propWriter.setProperty(
		new options._propPatch(dom, name, value, oldValue, isSvg)
	);
}

/**
 * Proxy an event to hooked event handlers
 * @param {PreactEvent} e The event object from the browser
 * @private
 */
function eventProxy(e) {
	if (this._listeners) {
		const eventHandler = this._listeners[e.type + false];
		/**
		 * This trick is inspired by Vue https://github.com/vuejs/core/blob/main/packages/runtime-dom/src/modules/events.ts#L90-L101
		 * when the dom performs an event it leaves micro-ticks in between bubbling up which means that an event can trigger on a newly
		 * created DOM-node while the event bubbles up, this can cause quirky behavior as seen in https://github.com/preactjs/preact/issues/3927
		 */
		if (!e._dispatched) {
			// When an event has no _dispatched we know this is the first event-target in the chain
			// so we set the initial dispatched time.
			e._dispatched = Date.now();
			// When the _dispatched is smaller than the time when the targetted event handler was attached
			// we know we have bubbled up to an element that was added during patching the dom.
		} else if (e._dispatched <= eventHandler._attached) {
			return;
		}
		return eventHandler(options.event ? options.event(e) : e);
	}
}

/**
 * Proxy an event to hooked event handlers
 * @param {PreactEvent} e The event object from the browser
 * @private
 */
function eventProxyCapture(e) {
	if (this._listeners) {
		return this._listeners[e.type + true](options.event ? options.event(e) : e);
	}
}

